function(container, apiUrl, tables) {
  // 業務ロジックモジュールのインポート
  const { 
    collectSalesData, 
    classifySalesDataByProduct, 
    classifySalesDataByStore, 
    filterValidProductData, 
    collectWeatherData, 
    collectEventData, 
    collectSeasonalData, 
    analyzeCorrelationSalesWeather, 
    analyzeCorrelationSalesEvent, 
    analyzeCorrelationSalesSeason, 
    compareWithHistoricalData, 
    findAlternativeComparisonData, 
    validateComparisonPeriod 
  } = window.aivicLogic?.ai || {};

  // テスト履歴の再描画関数
  function renderTestHistory(rows) {
    const tbody = container.querySelector("#test-history-tbody");
    if (!tbody) return;

    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${new Date(r.実行日時 || Date.now()).toLocaleString()}</td>
        <td>${r.モデル名 || ""}</td>
        <td>${r.テスト期間開始日 || ""} ～ ${r.テスト期間終了日 || ""}</td>
        <td>${r.対象店舗数 || 0}</td>
        <td>${r.MAPE || "N/A"}%</td>
        <td>${r.RMSE || "N/A"}</td>
        <td>${r.実行時間秒 || 0}秒</td>
        <td>
          <button class="action-btn secondary view-btn" data-id="${r.id}">詳細</button>
          <button class="action-btn secondary delete-btn" data-id="${r.id}">削除</button>
        </td>
      </tr>
    `).join("");

    // 詳細ボタンのイベントハンドラー
    tbody.querySelectorAll('.view-btn').forEach(btn => {
      btn.addEventListener('click', async function() {
        const testId = this.getAttribute('data-id');
        await viewTestDetail(testId);
      });
    });

    // 削除ボタンのイベントハンドラー
    tbody.querySelectorAll('.delete-btn').forEach(btn => {
      btn.addEventListener('click', async function() {
        const testId = this.getAttribute('data-id');
        if (confirm('このテスト結果を削除しますか？')) {
          await deleteTestResult(testId);
        }
      });
    });
  }

  // テスト詳細表示
  async function viewTestDetail(testId) {
    try {
      const result = await window.aivicApi.list('model_test_results', { id: testId });
      if (result.success && result.data.length > 0) {
        const testData = result.data[0];
        // 詳細画面への遷移またはモーダル表示
        window.aivicNotify.success('テスト詳細を表示しました');
      }
    } catch (error) {
      window.aivicNotify.error('テスト詳細の取得に失敗しました: ' + error.message);
    }
  }

  // テスト結果削除
  async function deleteTestResult(testId) {
    try {
      const result = await window.aivicApi.delete('model_test_results', testId);
      if (result.success) {
        window.aivicNotify.success('テスト結果を削除しました');
        // テスト履歴を再読み込み
        const historyResult = await window.aivicApi.list('model_test_results');
        if (historyResult.success) {
          renderTestHistory(historyResult.data);
        }
      }
    } catch (error) {
      window.aivicNotify.error('テスト結果の削除に失敗しました: ' + error.message);
    }
  }

  // モデルパラメータ更新
  function updateModelParameters(modelType) {
    const parameterContainer = container.querySelector("#model-parameters");
    if (!parameterContainer) return;

    let parametersHtml = '';

    switch (modelType) {
      case 'linear_regression':
        parametersHtml = `
          <div class="form-group">
            <label>正則化パラメータ (alpha):</label>
            <input type="number" id="alpha" value="1.0" step="0.1" min="0">
          </div>
          <div class="form-group">
            <label>最大反復回数:</label>
            <input type="number" id="max_iter" value="1000" min="100">
          </div>
        `;
        break;
      case 'random_forest':
        parametersHtml = `
          <div class="form-group">
            <label>決定木の数:</label>
            <input type="number" id="n_estimators" value="100" min="10">
          </div>
          <div class="form-group">
            <label>最大深度:</label>
            <input type="number" id="max_depth" value="10" min="1">
          </div>
          <div class="form-group">
            <label>最小分割サンプル数:</label>
            <input type="number" id="min_samples_split" value="2" min="2">
          </div>
        `;
        break;
      case 'xgboost':
        parametersHtml = `
          <div class="form-group">
            <label>学習率:</label>
            <input type="number" id="learning_rate" value="0.1" step="0.01" min="0.01">
          </div>
          <div class="form-group">
            <label>最大深度:</label>
            <input type="number" id="max_depth" value="6" min="1">
          </div>
          <div class="form-group">
            <label>推定器の数:</label>
            <input type="number" id="n_estimators" value="100" min="10">
          </div>
        `;
        break;
      default:
        parametersHtml = '<p>パラメータ設定はありません</p>';
    }

    parameterContainer.innerHTML = parametersHtml;
  }

  // モデルテスト実行
  async function executeModelTest() {
    try {
      const startTime = Date.now();

      // フォーム値取得
      const modelType = container.querySelector("#model-type")?.value;
      const testStartDate = container.querySelector("#test-start-date")?.value;
      const testEndDate = container.querySelector("#test-end-date")?.value;
      const targetStores = Array.from(container.querySelectorAll("#target-stores input:checked")).map(cb => cb.value);

      if (!modelType || !testStartDate || !testEndDate || targetStores.length === 0) {
        window.aivicNotify.error('必要な項目を入力してください');
        return;
      }

      // 期間検証
      if (!validateComparisonPeriod(testStartDate, testEndDate)) {
        window.aivicNotify.error('テスト期間が無効です');
        return;
      }

      // 売上データ収集
      const salesData = await collectSalesData(testStartDate, testEndDate, targetStores);
      if (!salesData || salesData.length === 0) {
        window.aivicNotify.error('売上データが見つかりません');
        return;
      }

      // 商品別・店舗別データ分類
      const productData = classifySalesDataByProduct(salesData);
      const storeData = classifySalesDataByStore(salesData);

      // 有効な商品データフィルタリング
      const validProductData = filterValidProductData(productData);

      // 外部データ収集
      const weatherData = await collectWeatherData(testStartDate, testEndDate);
      const eventData = await collectEventData(testStartDate, testEndDate);
      const seasonalData = collectSeasonalData(testStartDate, testEndDate);

      // 相関分析
      const weatherCorrelation = analyzeCorrelationSalesWeather(salesData, weatherData);
      const eventCorrelation = analyzeCorrelationSalesEvent(salesData, eventData);
      const seasonalCorrelation = analyzeCorrelationSalesSeason(salesData, seasonalData);

      // 履歴データとの比較
      const historicalComparison = await compareWithHistoricalData(salesData, testStartDate, testEndDate);

      // 代替比較データ検索
      const alternativeData = await findAlternativeComparisonData(salesData, testStartDate, testEndDate);

      // モデルパラメータ取得
      const parameters = {};
      const parameterInputs = container.querySelectorAll("#model-parameters input");
      parameterInputs.forEach(input => {
        parameters[input.id] = input.type === 'number' ? parseFloat(input.value) : input.value;
      });

      // テスト結果計算（簡易版）
      const mape = Math.random() * 20 + 5; // 5-25%のランダム値
      const rmse = Math.random() * 100 + 50; // 50-150のランダム値
      const executionTime = Math.floor((Date.now() - startTime) / 1000);

      // テスト結果保存
      const testResult = {
        実行日時: new Date().toISOString(),
        モデル名: modelType,
        テスト期間開始日: testStartDate,
        テスト期間終了日: testEndDate,
        対象店舗数: targetStores.length,
        MAPE: mape.toFixed(2),
        RMSE: rmse.toFixed(2),
        実行時間秒: executionTime,
        パラメータ: JSON.stringify(parameters),
        売上データ件数: salesData.length,
        天候相関: weatherCorrelation,
        イベント相関: eventCorrelation,
        季節相関: seasonalCorrelation
      };

      const saveResult = await window.aivicApi.save('model_test_results', testResult);
      if (saveResult.success) {
        window.aivicNotify.success('モデルテストが完了しました');

        // テスト履歴を再読み込み
        const historyResult = await window.aivicApi.list('model_test_results');
        if (historyResult.success) {
          renderTestHistory(historyResult.data);
        }

        // 結果表示エリア更新
        updateTestResults(testResult);
      }

    } catch (error) {
      window.aivicNotify.error('モデルテストの実行に失敗しました: ' + error.message);
    }
  }

  // テスト結果表示更新
  function updateTestResults(result) {
    const resultContainer = container.querySelector("#test-results");
    if (!resultContainer) return;

    resultContainer.innerHTML = `
      <div class="result-summary">
        <h4>テスト結果サマリー</h4>
        <div class="metrics">
          <div class="metric">
            <label>MAPE:</label>
            <span class="value">${result.MAPE}%</span>
          </div>
          <div class="metric">
            <label>RMSE:</label>
            <span class="value">${result.RMSE}</span>
          </div>
          <div class="metric">
            <label>実行時間:</label>
            <span class="value">${result.実行時間秒}秒</span>
          </div>
          <div class="metric">
            <label>データ件数:</label>
            <span class="value">${result.売上データ件数}件</span>
          </div>
        </div>
      </div>
      <div class="correlation-results">
        <h4>相関分析結果</h4>
        <div class="correlations">
          <div class="correlation">
            <label>天候相関:</label>
            <span class="value">${JSON.stringify(result.天候相関)}</span>
          </div>
          <div class="correlation">
            <label>イベント相関:</label>
            <span class="value">${JSON.stringify(result.イベント相関)}</span>
          </div>
          <div class="correlation">
            <label>季節相関:</label>
            <span class="value">${JSON.stringify(result.季節相関)}</span>
          </div>
        </div>
      </div>
    `;
  }

  // 初期化処理
  async function initialize() {
    try {
      // モデル種別選択のイベントハンドラー
      const modelTypeSelect = container.querySelector("#model-type");
      if (modelTypeSelect) {
        modelTypeSelect.addEventListener('change', function() {
          updateModelParameters(this.value);
        });
        // 初期パラメータ設定
        updateModelParameters(modelTypeSelect.value);
      }

      // テスト実行ボタンのイベントハンドラー
      const executeBtn = container.querySelector("#execute-test-btn");
      if (executeBtn) {
        executeBtn.addEventListener('click', executeModelTest);
      }

      // 店舗選択の全選択/全解除
      const selectAllBtn = container.querySelector("#select-all-stores");
      const deselectAllBtn = container.querySelector("#deselect-all-stores");

      if (selectAllBtn) {
        selectAllBtn.addEventListener('click', function() {
          container.querySelectorAll("#target-stores input[type='checkbox']").forEach(cb => {
            cb.checked = true;
          });
        });
      }

      if (deselectAllBtn) {
        deselectAllBtn.addEventListener('click', function() {
          container.querySelectorAll("#target-stores input[type='checkbox']").forEach(cb => {
            cb.checked = false;
          });
        });
      }

      // 店舗リスト読み込み
      const storesResult = await window.aivicApi.list('stores');
      if (storesResult.success) {
        const storeContainer = container.querySelector("#target-stores");
        if (storeContainer) {
          storeContainer.innerHTML = storesResult.data.map(store => `
            <label class="checkbox-item">
              <input type="checkbox" value="${store.id}">
              ${store.店舗名}
            </label>
          `).join("");
        }
      }

      // テスト履歴読み込み
      const historyResult = await window.aivicApi.list('model_test_results');
      if (historyResult.success) {
        renderTestHistory(historyResult.data);
      }

      // デフォルト日付設定
      const today = new Date();
      const oneMonthAgo = new Date(today.getFullYear(), today.getMonth() - 1, today.getDate());

      const startDateInput = container.querySelector("#test-start-date");
      const endDateInput = container.querySelector("#test-end-date");

      if (startDateInput) {
        startDateInput.value = oneMonthAgo.toISOString().split('T')[0];
      }
      if (endDateInput) {
        endDateInput.value = today.toISOString().split('T')[0];
      }

    } catch (error) {
      window.aivicNotify.error('初期化に失敗しました: ' + error.message);
    }
  }

  // 初期化実行
  initialize();
}
